def invert_dict(d):
    return {v: k for k, v in d.items()}


def merge_dicts(*dicts):
    result = {}
    for d in dicts:
        result.update(d)
    return result


def count_chars(text):
    counts = {}
    for char in text:
        counts[char] = counts.get(char, 0) + 1
    return counts
